import{_ as t,c as o,o as a,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Mini-Program Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miniapp-compatibility.md","filePath":"guide/miniapp-compatibility.md","lastUpdated":1791539557000}'),r={name:"guide/miniapp-compatibility.md"};function n(s,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="mini-program-compatibility" tabindex="-1">Mini-Program Compatibility <a class="header-anchor" href="#mini-program-compatibility" aria-label="Permalink to &quot;Mini-Program Compatibility&quot;">​</a></h1><blockquote><p><strong>This is the authoritative boundary.</strong> nPlyr runs hikerView-compatible mini-programs, but the original engine is <strong>Android / Java running Rhino</strong>, while nPlyr runs on Apple platforms with <strong>JavaScriptCore</strong> and <strong>no JVM</strong>. nPlyr reimplements the bridge and the rule DSL natively and adds a <strong>Rhino → Java compatibility layer</strong> for the Java APIs rules depend on. This page spells out what works unchanged, what works <em>through</em> the compat layer (with caveats), and what is <strong>not</strong> supported.</p></blockquote><p>If you are a user just trying a rule, read <a href="/guide/miniapps.html">Mini-Programs</a> first. This page is for understanding <em>why</em> a specific rule might differ from its Android behavior.</p><h2 id="why-a-boundary-exists" tabindex="-1">Why a boundary exists <a class="header-anchor" href="#why-a-boundary-exists" aria-label="Permalink to &quot;Why a boundary exists&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>hikerView (Android)</th><th>nPlyr (Apple)</th></tr></thead><tbody><tr><td>JS engine</td><td><strong>Rhino</strong> (Java-embedded)</td><td><strong>JavaScriptCore</strong></td></tr><tr><td>Can call Java?</td><td>Yes — <code>Packages.*</code>, <code>new JavaImporter()</code>, <code>with(){}</code> into any class</td><td>No JVM. A <strong>compat shim</strong> emulates a <em>subset</em> of the Java API</td></tr><tr><td>UI</td><td>Android <code>Activity</code> / <code>RecyclerView</code></td><td>Native SwiftUI</td></tr><tr><td>Network / storage</td><td>OkGo / LitePal</td><td>URLSession / UserDefaults</td></tr></tbody></table><p>So the <em>logic</em> ported 1:1 (the DSL, the <code>fba</code> bridge contract, the <code>hiker://</code> routing), but anything that reached into <strong>Java</strong> at runtime has to be re-provided — and that is deliberately a <strong>curated subset</strong>, not a full JRE.</p><p>nPlyr reimplements the bridge and the rule DSL natively and adds a compatibility layer that emulates a curated subset of the Java APIs rules depend on.</p><h2 id="✅-fully-supported-—-no-changes-needed" tabindex="-1">✅ Fully supported — no changes needed <a class="header-anchor" href="#✅-fully-supported-—-no-changes-needed" aria-label="Permalink to &quot;✅ Fully supported — no changes needed&quot;">​</a></h2><p>These behave the same as on Android; rules using only these will &quot;just work&quot;:</p><ul><li><strong>Rule DSL</strong>: <code>pdfh</code> / <code>pdfa</code> / <code>pd</code> selectors, <code>parseDom</code>, <code>setHomeResult</code> / <code>setSearchResult</code> / <code>setResult</code>.</li><li><strong><code>$</code> selector layer</strong> — including <code>$(url).lazyRule(fn)</code>, <code>$(url, ordinary).lazyRule</code>, and <code>.rule(fn)</code>.</li><li><strong><code>fy_bridge_app</code> (<code>fba</code>) bridge</strong>: play, <code>fetch</code>, <code>post</code>, <code>request</code>, parse, variable storage.</li><li><strong><code>hiker://</code> routing</strong>, including <code>hiker://empty##…</code> (lightweight parameter carrier) and <code>hiker://search?s=</code> (aggregated search).</li><li><strong><code>col_type</code> rendering</strong> — all <strong>38 layouts</strong> aligned with hikerView&#39;s own item templates.</li><li><strong>Variable map</strong>: <code>putVar</code> / <code>getVar</code> / <code>putMyVar</code> / <code>getMyVar</code> (in-memory) and <code>setItem</code> / <code>getItem</code> / <code>clearItem</code> (persisted to local storage).</li><li><strong>HTTP</strong>: <code>fetch</code> / <code>post</code> with headers; charset handling (<code>gb2312</code> / <code>gbk</code> / <code>gb18030</code> → GBK, <code>big5</code> → Big5, default UTF-8); <code>withHeaders</code> / <code>onlyHeaders</code> / <code>withStatusCode</code> return a JSON envelope.</li><li><strong>User-Agent</strong>: <code>auto</code> / <code>mobile</code> / <code>pc</code> / custom (a rule&#39;s own UA applies when you choose to follow it).</li><li><strong>Cloud shares</strong>: TextDB (云2), <code>cmd.im</code> 302 redirect (云5), <code>pasteme</code> (云6).</li><li><strong>Crypto</strong> that is pure-JS (<code>AES</code>, <code>CryptoJS</code>); <code>RSA</code> where the native bridge provides it.</li><li><strong><code>;post;</code> pre-fetch</strong> and <code>decodeConflictStr</code> decoding.</li></ul><h2 id="⚠️-supported-through-the-java-compatibility-layer-subset-only" tabindex="-1">⚠️ Supported <em>through</em> the Java compatibility layer (subset only) <a class="header-anchor" href="#⚠️-supported-through-the-java-compatibility-layer-subset-only" aria-label="Permalink to &quot;⚠️ Supported *through* the Java compatibility layer (subset only)&quot;">​</a></h2><p>The layer provides these globals and classes, but each has caveats:</p><ul><li><strong>Globals</strong>: <code>Packages</code>, <code>java</code>, <code>JavaImporter</code>, <code>importPackage()</code>, <code>importClass()</code>.</li><li><strong><code>_base64</code></strong> mirroring <code>android.util.Base64</code> semantics.</li><li><strong><code>FileUtil</code></strong> (<code>com.example.hikerview.utils</code>) — provided as a <em>native shim</em> (see <code>toInputStream</code> below).</li><li><strong><code>javax.crypto</code></strong>: <code>Cipher.getInstance</code> / <code>init</code> / <code>doFinal</code>, <code>SecretKeySpec</code>, <code>IvParameterSpec</code> — but <strong><code>Cipher.update</code> is not implemented</strong> (it throws a clear &quot;not used by corpus, report the rule name&quot; error rather than silently misbehaving).</li></ul><h3 id="known-class-list-the-big-one" tabindex="-1">Known-class list (the big one) <a class="header-anchor" href="#known-class-list-the-big-one" aria-label="Permalink to &quot;Known-class list (the big one)&quot;">​</a></h3><p>Only a <strong>curated set</strong> of Java classes is shimmed. A class <strong>not</strong> on the list falls back to a <strong>diagnostic stub</strong>: it logs once and throws a <em>clear</em> error on use — it does <strong>not</strong> produce a bare <code>ReferenceError</code>. In practice this means:</p><ul><li>Rules that use common, well-known Java classes (the ones the corpus needs) work.</li><li>Rules that reach into obscure or Android-framework classes will fail with an actionable message naming the missing class — please report the rule name so the list can grow.</li></ul><h3 id="byte-has-two-representations" tabindex="-1"><code>byte[]</code> has two representations <a class="header-anchor" href="#byte-has-two-representations" aria-label="Permalink to &quot;`byte[]` has two representations&quot;">​</a></h3><p>This trips up image-decryption rules in particular:</p><ul><li><strong>Small buffers (≤ 4096 B)</strong> → a real JS <code>Array&lt;number&gt;</code> with a <code>.length</code> <em>property</em> (Java-array semantics) and working bitwise ops (e.g. a typical <code>toHex</code> pattern found in image-decryption rules).</li><li><strong>Large buffers (images, etc.)</strong> → a host-provided byte-array object exposing only <code>length</code> / <code>toBase64</code> / <code>toHex</code> / <code>utf8String</code> / <code>slice</code>. You <strong>cannot</strong> do per-byte access on the large form — third-party image-decryption chains rely on the host methods instead.</li></ul><h3 id="fileutil-toinputstream" tabindex="-1"><code>FileUtil.toInputStream</code> <a class="header-anchor" href="#fileutil-toinputstream" aria-label="Permalink to &quot;`FileUtil.toInputStream`&quot;">​</a></h3><p>On Android this returns a Java <code>InputStream</code>. nPlyr <strong>replaces</strong> that path: it intercepts an intercepted-stream marker, converts it to a local picture URL served from the app&#39;s cache, and hands the image back to the view. A rule that expects to <em>read the stream itself</em> must rely on this host conversion rather than opening an <code>InputStream</code>.</p><h3 id="java-file-i-o-is-minimal" tabindex="-1">Java File I/O is minimal <a class="header-anchor" href="#java-file-i-o-is-minimal" aria-label="Permalink to &quot;Java File I/O is minimal&quot;">​</a></h3><p>the emulated files root returns <code>&#39;/&#39;</code> and <code>fileExist</code> returns a boolean — a tiny shim. Arbitrary <code>java.io.File</code> / NIO / <code>Zip</code> / <code>java.net.*</code> operations are <strong>not</strong> available; use the <code>fetch</code> / <code>post</code> bridge for anything network-related.</p><h3 id="bigdecimal-scale" tabindex="-1"><code>BigDecimal</code> scale <a class="header-anchor" href="#bigdecimal-scale" aria-label="Permalink to &quot;`BigDecimal` scale&quot;">​</a></h3><p>Android&#39;s <code>BigDecimal</code> keeps scale (e.g. <code>&quot;5.0&quot;</code>). nPlyr&#39;s decimal formatting preserves scale too, or numeric formatting drifts. Rules depending on exact Java <code>BigDecimal</code><code>toString</code> output may see differences.</p><h3 id="rhino-engine-semantics" tabindex="-1">Rhino engine semantics <a class="header-anchor" href="#rhino-engine-semantics" aria-label="Permalink to &quot;Rhino engine semantics&quot;">​</a></h3><p>A top-level <code>const X = X = …</code> double-assignment is tolerated by Rhino but <strong>crashes JavaScriptCore</strong>. nPlyr runs a script preprocessor so such degenerate JS doesn&#39;t take down the engine. Rhino-only quirks are therefore neutralized, not emulated.</p><h3 id="hijackenv-method-bridges" tabindex="-1"><code>hijackEnv</code> <code>method_*</code> bridges <a class="header-anchor" href="#hijackenv-method-bridges" aria-label="Permalink to &quot;`hijackEnv` `method_*` bridges&quot;">​</a></h3><p>Java method hijacking is supported, but the native bridge must delegate to the original method it captured at injection time — <strong>never</strong> call back into the JS global, or you get infinite recursion (<code>Maximum call stack size exceeded</code>). A bridge that returns no-op silently disables the dynamic card that depended on it.</p><h2 id="❌-not-supported" tabindex="-1">❌ Not supported <a class="header-anchor" href="#❌-not-supported" aria-label="Permalink to &quot;❌ Not supported&quot;">​</a></h2><ul><li><strong>Arbitrary Java classes beyond the known list</strong> — there is no JVM and no reflection into the Android framework.</li><li><strong>Android UI / View / Activity / RecyclerView / Adapter</strong> APIs — nPlyr renders natively; these have no counterpart.</li><li><strong>Android permissions, Content Providers, the Intent system.</strong></li><li><strong>Some <code>javax.crypto</code> paths</strong> — <code>Cipher.update</code>, and any cipher mode the native bridge has not implemented.</li><li><strong><code>java.io.File</code> / NIO / Zip / <code>java.net.*</code></strong> — use the <code>fetch</code> / <code>post</code> bridge instead.</li></ul><h2 id="reporting-an-incompatibility" tabindex="-1">Reporting an incompatibility <a class="header-anchor" href="#reporting-an-incompatibility" aria-label="Permalink to &quot;Reporting an incompatibility&quot;">​</a></h2><p>When a specific rule misbehaves, capture:</p><ol><li>the <strong>rule name</strong>,</li><li>the <strong>step</strong> it failed at (home / search / detail / parse), and</li><li>the <strong>message</strong> — the compat layer logs a clear one-liner for unlisted classes.</li></ol><p>Report these so the known-class list and the native bridges can be extended.</p><h2 id="tips-for-rule-authors" tabindex="-1">Tips for rule authors <a class="header-anchor" href="#tips-for-rule-authors" aria-label="Permalink to &quot;Tips for rule authors&quot;">​</a></h2><ul><li>Replace <code>java.io.File</code> / stream reading with the <code>fetch</code> / <code>post</code> bridge, or with the host&#39;s <code>toInputStream</code> conversion that returns a local picture URL.</li><li>Don&#39;t depend on obscure Java classes; prefer the JS or bridge equivalents.</li><li>Avoid Rhino-only idioms such as the <code>const X = X = …</code> double assignment.</li><li>Keep per-byte image work on <strong>small</strong> buffers; for large images use the <code>toBase64</code> / <code>toHex</code> / <code>slice</code> host methods.</li></ul><h2 id="official-hikerview-documentation" tabindex="-1">Official hikerView documentation <a class="header-anchor" href="#official-hikerview-documentation" aria-label="Permalink to &quot;Official hikerView documentation&quot;">​</a></h2><p>nPlyr aims to be compatible with the hikerView rule ecosystem. For the complete, authoritative reference — the rule DSL, selectors, the mini-program bridge contract and authoring guides — consult the official hikerView documentation:</p><ul><li><strong>hikerView Docs:</strong> <a href="https://github.com/ReflectionLab/Documents" target="_blank" rel="noreferrer">https://github.com/ReflectionLab/Documents</a></li></ul><p>Rule authors coming from hikerView can use the same share texts and JSON; the compatibility boundary documented above explains where nPlyr diverges from the Android runtime.</p>',41)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
